package com.levi.pocketdj.playback.dj

import com.levi.pocketdj.playback.dj.DjSetPlanner.Candidate
import com.levi.pocketdj.playback.dj.DjSetPlanner.Options
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.UUID

/** Port of iOS DJSetPlannerTests plus goldens generated by the real Swift planner. */
class DjSetPlannerTest {

    private fun song(
        id: String, bpm: Double? = null, key: String? = null, genre: String? = null, year: Int? = null,
        cols: Set<String> = emptySet(), fixed: Boolean = false, artists: Set<String> = emptySet(),
    ) = Candidate(songId = id, bpm = bpm, camelot = key, genre = genre, year = year, collections = cols,
        fixed = fixed, artists = artists)

    private fun seed(wave0: Int? = null, pocket0: Int? = null, pocket1: Int? = null): ULong {
        for (s in 1uL..10_000uL) {
            if (wave0 != null && DjSetPlanner.waveLength(s, 0) != wave0) continue
            if (pocket0 != null && DjSetPlanner.pocketLength(s, 0) != pocket0) continue
            if (pocket1 != null && DjSetPlanner.pocketLength(s, 1) != pocket1) continue
            return s
        }
        error("no seed")
    }

    private fun ordered(up: List<Candidate>, order: List<UUID>): List<Candidate> {
        val by = up.associateBy { it.uid }
        return order.map { by.getValue(it) }
    }

    private fun bands(songs: List<Candidate>) = songs.mapNotNull { it.features.band }
    private val tempoOnly = Options(tempoWaves = true, pockets = false, key = false)
    private fun st(seed: ULong) = DjPlannerState(seed)

    // ---- tempo waves
    private val widePool get() = listOf(
        song("a", 101.0), song("b", 121.0), song("c", 113.0), song("d", 104.0), song("e", 117.0), song("f", 125.0),
        song("g", 111.0), song("h", 108.0), song("i", 115.0), song("j", 119.0), song("k", 129.0), song("l", 112.0),
    )

    @Test fun wavesBuildAndFall() {
        val pool = widePool
        val r = DjSetPlanner.plan(null, pool, st(seed(wave0 = 2)), tempoOnly)
        assertEquals(listOf(100, 100, 100, 110, 110, 110, 120, 120, 120, 110, 110, 110), bands(ordered(pool, r.order)))
    }

    @Test fun threeBandWaveClimbsThenFlips() {
        val pool = (0 until 3).flatMap { i -> listOf(100, 110, 120, 130).map { song("s$it-$i", (it + i).toDouble()) } } +
            (0 until 3).map { song("t$it", (125 + it).toDouble()) }
        val r = DjSetPlanner.plan(null, pool, st(seed(wave0 = 3)), tempoOnly)
        assertEquals(listOf(100, 100, 100, 110, 110, 110, 120, 120, 120, 130, 130, 130, 120, 120, 120),
            bands(ordered(pool, r.order)))
    }

    @Test fun minimumThreePerBandCountsAlreadyPlayed() {
        val pool = listOf(song("x1", 112.0), song("x2", 114.0), song("x3", 116.0), song("a1", 101.0), song("a2", 108.0))
        val r = DjSetPlanner.plan(song("cur", 105.0), pool, st(7uL), tempoOnly)
        assertEquals(listOf(100, 100, 110, 110, 110), bands(ordered(pool, r.order)))
        assertEquals(100, r.state.band)
        assertEquals(1, r.state.playedInBand)

        var s = st(7uL)
        for (b in listOf(101.0, 103.0, 107.0)) s = DjSetPlanner.plan(song("p$b", b), emptyList(), s, tempoOnly).state
        assertEquals(3, s.playedInBand)
        val pool2 = listOf(song("a", 104.0), song("b", 113.0), song("c", 114.0), song("d", 115.0))
        val r2 = DjSetPlanner.plan(null, pool2, s, tempoOnly)
        assertEquals(listOf(110, 110, 110, 100), bands(ordered(pool2, r2.order)))
    }

    @Test fun earlyFlipAtPoolEdge() {
        val pool = widePool
        val r = DjSetPlanner.plan(null, pool, st(seed(wave0 = 3)), tempoOnly)
        assertEquals(listOf(100, 100, 100, 110, 110, 110, 120, 120, 120, 110, 110, 110), bands(ordered(pool, r.order)))
    }

    @Test fun sparseBandIsSkippedTowardPopulatedBand() {
        val pool = listOf(song("a", 101.0), song("s", 112.0), song("b", 103.0), song("c", 105.0),
            song("d", 121.0), song("e", 123.0), song("f", 125.0))
        val r = DjSetPlanner.plan(null, pool, st(seed(wave0 = 3)), tempoOnly)
        val ids = ordered(pool, r.order).map { it.songId }
        assertEquals(listOf("a", "b", "c"), ids.subList(0, 3).sorted())
        assertEquals(listOf("d", "e", "f"), ids.subList(3, 6).sorted())
        assertEquals("s", ids.last())
    }

    // ---- degrade / fixed
    @Test fun noMetadataKeepsOrder() {
        val pool = (0 until 12).map { song("n$it") }
        for (o in listOf(Options.ALL_ON, tempoOnly, Options(false, false, false))) {
            val r = DjSetPlanner.plan(song("cur", 120.0, "8A", "rock", 1990), pool, st(42uL), o)
            assertEquals(pool.map { it.uid }, r.order)
        }
    }

    @Test fun allOptionsOffKeepsOrderEvenWithMetadata() {
        val pool = listOf(song("a", 150.0, "1A", "rock", 1970), song("b", 90.0, "8B", "jazz", 2010),
            song("c", 121.0, "8A", "rock", 1990))
        val r = DjSetPlanner.plan(song("cur", 120.0, "8A", "rock", 1990), pool, st(1uL), Options(false, false, false))
        assertEquals(pool.map { it.uid }, r.order)
    }

    @Test fun fixedRowsKeepTheirPositions() {
        val pool = listOf(song("a", 140.0), song("b", 101.0), song("pin", 150.0, fixed = true), song("c", 103.0),
            song("d", 130.0), song("jbx", fixed = true), song("e", 105.0), song("f", 107.0))
        val r = DjSetPlanner.plan(song("cur", 104.0), pool, st(3uL), Options.ALL_ON)
        assertEquals(pool[2].uid, r.order[2])
        assertEquals(pool[5].uid, r.order[5])
        assertEquals(pool.map { it.uid }.toSet(), r.order.toSet())
        assertEquals(pool.size, r.order.size)
        assertNotEquals(pool.map { it.uid }, r.order)
    }

    @Test fun bufferedNextRowIsHeld() {
        val pool = listOf(song("next", 150.0, fixed = true), song("a", 101.0), song("b", 103.0))
        val r = DjSetPlanner.plan(song("cur", 102.0), pool, st(9uL), Options.ALL_ON)
        assertEquals(pool[0].uid, r.order.first())
        val free = listOf(pool[0].copy(fixed = false)) + pool.drop(1)
        val r2 = DjSetPlanner.plan(song("cur", 102.0), free, st(9uL), Options.ALL_ON)
        assertEquals(pool[0].uid, r2.order.last())
    }

    @Test fun noBpmSongsNeverBreakTheCount() {
        val pool = listOf(song("a", 101.0), song("nil", fixed = true), song("x", 112.0), song("b", 108.0),
            song("y", 115.0), song("z", 118.0))
        val r = DjSetPlanner.plan(song("cur", 105.0), pool, st(5uL), tempoOnly)
        val o = ordered(pool, r.order)
        assertEquals("nil", o[1].songId)
        assertEquals(listOf(100, 100, 110, 110, 110), bands(o))
    }

    @Test fun keyOnlySongPlacedByKeyFit() {
        val pool = listOf(song("a", 101.0), song("b", 109.0), song("keyed", key = "8A"))
        val r = DjSetPlanner.plan(song("cur", 105.0, "8A"), pool, st(5uL), Options(true, false, true))
        assertEquals("keyed", ordered(pool, r.order).first().songId)
        val pool2 = listOf(song("bare"), song("a", 104.0), song("b", 106.0))
        val r2 = DjSetPlanner.plan(song("cur", 105.0), pool2, st(5uL), tempoOnly)
        assertEquals(listOf("a", "b", "bare"), ordered(pool2, r2.order).map { it.songId })
    }

    @Test fun keyBreaksTempoTies() {
        val pool = listOf(song("far", 106.0, "3B"), song("near", 106.0, "9A"))
        val r = DjSetPlanner.plan(song("cur", 106.0, "8A"), pool, st(1uL), Options.ALL_ON)
        assertEquals("near", ordered(pool, r.order).first().songId)
    }

    // ---- pockets
    @Test fun pocketLengthsAreThreeToFour() {
        val s = seed(pocket0 = 3, pocket1 = 4)
        val pool = (0 until 8).flatMap { i -> listOf(song("X$i", genre = "rock", year = 1980), song("Y$i", genre = "jazz", year = 1982)) }
        val r = DjSetPlanner.plan(null, pool, st(s), Options(true, true, true))
        val letters = ordered(pool, r.order).map { it.songId.take(1) }
        val runs = ArrayList<Int>()
        letters.forEachIndexed { i, l -> if (i > 0 && letters[i - 1] == l) runs[runs.size - 1]++ else runs.add(1) }
        assertEquals("X", letters.first())
        assertEquals(listOf(3, 4, DjSetPlanner.pocketLength(s, 2)), runs.take(3))
    }

    @Test fun nextPocketAnchorIsNearAdjacent() {
        val s = seed(pocket0 = 3)
        fun x(i: Int) = song("X$i", genre = "rock", year = 1980, cols = setOf("c1"))
        val pool = listOf(x(1), x(2), song("Z", genre = "pop", year = 2015, cols = setOf("c9")), x(3),
            song("Y", genre = "jazz", year = 1982, cols = setOf("c1")))
        val opts = Options(false, true, false)
        val r = DjSetPlanner.plan(x(0), pool, st(s), opts)
        assertEquals(listOf("X1", "X2", "Y"), ordered(pool, r.order).map { it.songId }.take(3))
        val pool2 = listOf(x(1), x(2), song("Z", genre = "pop", year = 2015), x(3))
        val r2 = DjSetPlanner.plan(x(0), pool2, st(s), opts)
        assertEquals("Z", ordered(pool2, r2.order)[2].songId)
    }

    @Test fun similarityRenormalizesOverKnownParts() {
        fun f(bpm: Double? = null, camelot: String? = null, genre: String? = null, year: Int? = null,
              cols: Set<String> = emptySet()) = DjFeatures.of(bpm, camelot, genre, year, cols)
        assertNull(DjSetPlanner.similarity(f(genre = "rock"), f(year = 1990)))
        assertEquals(1.0, DjSetPlanner.similarity(f(genre = "rock"), f(genre = "Rock"))!!, 0.0)
        assertEquals(0.5, DjSetPlanner.similarity(f(genre = "rock", year = 1990), f(genre = "jazz", year = 1990))!!, 0.0)
        assertEquals(1.0 / 3, DjSetPlanner.similarity(f(cols = setOf("a", "b")), f(cols = setOf("b", "c")))!!, 1e-9)
        assertEquals(Math.exp(-1.0), DjSetPlanner.similarity(f(year = 1990), f(year = 1996))!!, 1e-9)
        assertNull(f(genre = "Other").genre)
        assertEquals(120.0, f(bpm = 60.0).bpm!!, 0.0)
        assertEquals(120, f(bpm = 60.0).band)
        assertNull(f(camelot = "H#").camelot)
        assertEquals("8A", f(camelot = " 8a").camelot)
        val c = DjSetPlanner.candidate(UUID.randomUUID(), "s", 100.0, "8A", "Boom Bap", 0, emptySet(), false)
        assertEquals("hip-hop", c.genre)
        assertNull(c.year)
    }

    // ---- state / determinism
    @Test fun accountingIsIdempotentPerUid() {
        val cur = song("cur", 105.0, genre = "rock")
        val a = DjSetPlanner.plan(cur, emptyList(), st(1uL), Options.ALL_ON).state
        val b = DjSetPlanner.plan(cur, listOf(song("q", 140.0)), a, Options.ALL_ON).state
        assertEquals(a, b)
        assertEquals(1, b.playedInBand)
        assertEquals(1, b.pocketCount)
        assertEquals(b, DjPlannerState.decode(b.encode()))
    }

    @Test fun planDoesNotMutateInputState() {
        val s = st(5uL)
        val before = s.copy()
        DjSetPlanner.plan(song("cur", 105.0), listOf(song("a", 140.0), song("b", 101.0)), s, Options.ALL_ON)
        assertEquals(before, s)
    }

    @Test fun seededLengthsCoverTheirRanges() {
        assertEquals(setOf(2, 3), (0 until 64).map { DjSetPlanner.waveLength(12345uL, it) }.toSet())
        assertEquals(setOf(3, 4), (0 until 64).map { DjSetPlanner.pocketLength(12345uL, it) }.toSet())
    }

    @Test fun hashMatchesSwiftGoldens() {
        // Computed from the iOS formula (SplitMix64 finalizer over seed/salt/index).
        assertEquals(12627476488779701228uL, DjSetPlanner.hash(1uL, 0x57A7EuL, 0))
        assertEquals(12016828446512529758uL, DjSetPlanner.hash(42uL, 0x90C4E7uL, 3))
        assertEquals(4275026891917292156uL, DjSetPlanner.hash((1uL shl 63) + 5uL, 0x57A7EuL, 2))
        assertEquals(5430444928723478255uL, DjSetPlanner.hash(ULong.MAX_VALUE, 0x90C4E7uL, 0))
        assertEquals(4, DjSetPlanner.pocketLength(ULong.MAX_VALUE, 0))
        assertEquals(2, DjSetPlanner.waveLength(1uL, 0))
    }

    // ---- artist spacing / scarcity / aging
    @Test fun artistSpacingBreaksAPocketCollapse() {
        fun s(id: String, artist: String, bpm: Double, cols: Set<String>) =
            Candidate(songId = id, bpm = bpm, genre = "hip-hop", year = 2017, collections = cols, artists = setOf(artist))
        val tight = setOf("potential", "drive")
        val cur = s("cur", "goldlink", 100.0, tight)
        val up = listOf(
            s("g1", "goldlink", 100.0, tight), s("c1", "cousin stizz", 101.0, tight),
            s("g2", "goldlink", 101.0, tight), s("c2", "cousin stizz", 100.0, tight),
            s("x1", "phonte", 104.0, setOf("other")), s("x2", "sir", 106.0, setOf("other")),
            s("x3", "lady wray", 103.0, setOf("other")), s("x4", "kenny muney", 105.0, setOf("other")),
        )
        val r = DjSetPlanner.plan(cur, up, st(1uL), Options.ALL_ON)
        val played = listOf(cur) + ordered(up, r.order)
        played.forEachIndexed { i, c ->
            val window = played.subList(maxOf(0, i - DjSetPlanner.ARTIST_SPACING + 1), i)
            assertFalse("${c.songId} repeats an artist: ${played.map { it.songId }}",
                window.any { w -> w.artists.any { it in c.artists } })
        }
    }

    @Test fun artistSpacingYieldsWhenImpossible() {
        val up = (0 until 5).map { Candidate(songId = "a$it", bpm = 100.0 + it, artists = setOf("solo")) }
        val r = DjSetPlanner.plan(Candidate(songId = "cur", bpm = 100.0, artists = setOf("solo")), up, st(1uL), Options.ALL_ON)
        assertEquals(up.map { it.uid }.toSet(), r.order.toSet())
    }

    @Test fun artistSpacingCountsAnySharedCredit() {
        val cur = Candidate(songId = "cur", bpm = 100.0, artists = setOf("goldlink"))
        val up = listOf(Candidate(songId = "feat", bpm = 100.0, artists = setOf("kaytranada", "goldlink")),
            Candidate(songId = "far", bpm = 140.0, artists = setOf("sir")))
        val r = DjSetPlanner.plan(cur, up, st(1uL), tempoOnly)
        assertEquals(listOf("far", "feat"), ordered(up, r.order).map { it.songId })
    }

    /** cdbf9e87: an artist with too many rows to space out plays as soon as spacing allows. */
    @Test fun scarcityPullsAnOverrepresentedArtistForward() {
        fun o(i: Int) = Candidate(songId = "o$i", bpm = 100.0 + i, genre = "rock", year = 1990, artists = setOf("other$i"))
        fun g(i: Int) = Candidate(songId = "g$i", bpm = 150.0, genre = "jazz", year = 1960, artists = setOf("goldlink"))
        val cur = Candidate(songId = "cur", bpm = 100.0, genre = "rock", year = 1990, artists = setOf("host"))
        val up = (0 until 6).map { o(it) } + (0 until 3).map { g(it) }
        val r = DjSetPlanner.plan(cur, up, st(1uL), Options.ALL_ON)
        val ids = ordered(up, r.order).map { it.songId }
        assertEquals(listOf(0, 4, 8), ids.withIndex().filter { it.value.startsWith("g") }.map { it.index })
    }

    @Test fun agingOutweighsOrderBonusAndBreaksTies() {
        val a = song("A", 100.0)
        val b = song("B", 100.0)
        val plain = DjSetPlanner.plan(song("cur", 100.0), listOf(a, b), st(1uL), tempoOnly)
        assertEquals(listOf(a.uid, b.uid), plain.order)
        val aged = DjSetPlanner.plan(song("cur", 100.0), listOf(a, b.copy(deferrals = 2)), st(1uL), tempoOnly)
        assertEquals(listOf(b.uid, a.uid), aged.order)
    }

    // ---- JSON (iOS Codable shape)
    @Test fun seedAtOrAbove2To63RoundTripsUnsigned() {
        val s = DjPlannerState(ULong.MAX_VALUE - 6uL)
        val json = s.encode()
        assertTrue(json, json.contains("\"seed\":18446744073709551609"))
        assertEquals(ULong.MAX_VALUE - 6uL, DjPlannerState.decode(json)!!.seed)
        val big = DjPlannerState((1uL shl 63) + 12345uL).apply { band = 120; lastAccountedUid = UUID.randomUUID() }
        assertEquals(big, DjPlannerState.decode(big.encode()))
    }

    @Test fun decodesSwiftEncodedState() {
        val swift = """{"pocketIndex":0,"pocketLength":3,"direction":1,"waveIndex":0,"waveLength":2,"playedInBand":0,"pocketCount":0,"bandSteps":0,"seed":18446744073709551609}"""
        val d = DjPlannerState.decode(swift)!!
        assertEquals(ULong.MAX_VALUE - 6uL, d.seed)
        assertNull(d.band); assertNull(d.pocketAnchor); assertNull(d.lastAccountedUid)
        assertEquals(DjDirection.UP, d.direction)
        // iOS-written JSON without the optionals re-encodes without them.
        val re = d.encode()
        assertFalse(re.contains("\"band\"")); assertFalse(re.contains("pocketAnchor")); assertFalse(re.contains("lastAccountedUid"))
    }

    @Test fun decodesAnchorDirectionAndUuid() {
        val j = """{"seed":7,"band":120,"playedInBand":2,"direction":-1,"bandSteps":1,"waveIndex":2,"waveLength":3,
            "pocketAnchor":{"bpm":121.5,"camelot":"8A","genre":"rock","year":1990,"collections":["b","a"]},
            "pocketCount":2,"pocketIndex":1,"pocketLength":4,"lastAccountedUid":"0A1B2C3D-0000-4000-8000-0123456789AB"}"""
        val d = DjPlannerState.decode(j)!!
        assertEquals(DjDirection.DOWN, d.direction)
        assertEquals(setOf("a", "b"), d.pocketAnchor!!.collections)
        assertEquals(121.5, d.pocketAnchor!!.bpm!!, 0.0)
        assertNotNull(d.lastAccountedUid)
        val re = d.encode()
        assertTrue(re, re.contains("\"lastAccountedUid\":\"0A1B2C3D-0000-4000-8000-0123456789AB\""))
        assertEquals(d, DjPlannerState.decode(re))
        assertNull(DjPlannerState.decode("{\"band\":1}"))
        assertNull(DjPlannerState.decode("not json"))
    }

