    @Test fun ordersMatchSwiftPlannerOnRandomBattery() {
        val rng = com.levi.pocketdj.playback.dj.AutoTransition.Rng(20261123uL)
        fun next() = AutoTransition.splitmix64(rng)
        val genres = listOf("rock", "jazz", "soul", "hip-hop", null)
        val pool = listOf("a", "b", "c", "d", "e", "f")
        for (t in 0 until 30) {
            val n = 6 + (next() % 30uL).toInt()
            fun uid(i: Int) = UUID(t.toLong(), i.toLong())
            fun mk(i: Int): Candidate {
                val r = next(); val r2 = next()
                val arts = HashSet<String>()
                if (r2 % 5uL != 0uL) arts.add(pool[((r2 shr 8).toLong() % (if (t % 2 == 0) 3 else 6)).toInt()])
                if (r2 % 11uL == 0uL) arts.add(pool[((r2 shr 16).toLong() % 6).toInt()])
                return Candidate(
                    uid = uid(i), songId = "s$i",
                    bpm = if (r % 6uL == 0uL) null else 62 + (r % 110uL).toDouble() + ((r shr 40) % 10uL).toDouble() / 10,
                    camelot = if (r % 3uL == 0uL) null else "${1 + ((r shr 4) % 12uL).toInt()}${if (r % 2uL == 0uL) "A" else "B"}",
                    genre = genres[((r shr 8) % 5uL).toInt()],
                    year = if (r % 7uL == 0uL) null else 1960 + ((r shr 16) % 60uL).toInt(),
                    collections = if (r % 4uL == 0uL) emptySet() else setOf("c${(r shr 24) % 5uL}", "d${(r shr 28) % 3uL}"),
                    fixed = (r shr 32) % 11uL == 0uL, artists = arts,
                    deferrals = if (((r2 shr 24) % 4uL).toInt() == 0) ((r2 shr 32) % 8uL).toInt() else 0,
                    anchor = (r2 shr 40) % 13uL == 0uL,
                )
            }
            val cur = mk(0)
            val up = (1 until n).map { mk(it) }
            val seed = next()
            val opts = Options(tempoWaves = t % 5 != 3, pockets = t % 7 != 4, key = t % 4 != 1)
            val r = DjSetPlanner.plan(cur, up, DjPlannerState(seed), opts)
            val idx = r.order.map { u -> up.indexOfFirst { it.uid == u } + 1 }
            val line = "$t $seed ${idx.joinToString(",")} ${r.state.band ?: -1} ${r.state.pocketCount} ${r.state.waveLength} ${r.state.pocketLength}"
            assertEquals(golden[t], line)
        }
    }
}
